{
  "implementation": "def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    failure_entries = {}
    success_entries = []
    for i, trial in enumerate(trials):
        sig = trial['signature']
        refl = trial['reflection']
        succ = trial['success']
        if not succ:
            if sig in failure_entries:
                failure_entries[sig]['last_trial'] = i
                failure_entries[sig]['reflection'] = refl
            else:
                failure_entries[sig] = {
                    'last_trial': i,
                    'reflection': refl,
                    'signature': sig,
                    'success': False
                }
        else:
            success_entries.append({
                'last_trial': i,
                'reflection': refl,
                'signature': sig,
                'success': True
            })
    all_entries = list(failure_entries.values()) + success_entries
    if len(all_entries) <= capacity:
        all_entries.sort(key=lambda e: e['last_trial'])
        return {'memory': all_entries, 'signatures': [e['signature'] for e in all_entries]}
    all_entries.sort(key=lambda e: (e['success'], -e['last_trial'], e['signature']))
    selected = all_entries[:capacity]
    selected.sort(key=lambda e: e['last_trial'])
    return {'memory': selected, 'signatures': [e['signature'] for e in selected]}"
}
